  oauthStatus: Extract<OAuthStatus, { state: 'apikey_setup' }>
  setOAuthStatus: (status: OAuthStatus) => void
  onDone: () => void
}

function ApiKeySetupScreen({ oauthStatus, setOAuthStatus, onDone }: ApiKeySetupScreenProps): React.ReactNode {
  const [step, setStep] = React.useState<'provider' | 'key'>('provider')
  const [provider, setProvider] = React.useState<'openai' | 'deepseek' | 'gemini'>(oauthStatus.provider)
  const [apiKey, setApiKey] = React.useState('')
  const [cursorOffset, setCursorOffset] = React.useState(0)
  const [saved, setSaved] = React.useState(false)

  const providerOptions = [
    { label: <Text>OpenAI · <Text dimColor>GPT-4o, o3, o4-mini, etc.</Text>{'\n'}</Text>, value: 'openai' as const },
    { label: <Text>DeepSeek · <Text dimColor>deepseek-chat, deepseek-reasoner</Text>{'\n'}</Text>, value: 'deepseek' as const },
