import React, { useState } from 'react'
import { Box, Text, useInput } from 'ink'
import { homedir } from 'os'
import { join } from 'path'

const CONFIG_PATH = join(homedir(), '.deepseek-code', 'config.json')

async function saveApiKey(key: string): Promise<void> {
  const dir = join(homedir(), '.deepseek-code')
  await Bun.write(join(dir, '.gitkeep'), '')
  const existing = await Bun.file(CONFIG_PATH).json().catch(() => ({}))
  await Bun.write(CONFIG_PATH, JSON.stringify({ ...existing, DEEPSEEK_API_KEY: key }, null, 2))
  process.env.DEEPSEEK_API_KEY = key
}

export async function loadSavedApiKey(): Promise<string | null> {
  try {
    const cfg = await Bun.file(CONFIG_PATH).json()
    return cfg.DEEPSEEK_API_KEY ?? null
  } catch {
    return null
  }
}

interface Props {
  onDone(): void
}

export function ApiKeySetup({ onDone }: Props) {
  const [input, setInput] = useState('')
  const [saved, setSaved] = useState(false)
  const [error, setError] = useState('')

  useInput(async (char, key) => {
    if (saved) return

    if (key.return) {
      const trimmed = input.trim()
      if (!trimmed) {
        setError('API key cannot be empty.')
        return
      }
      try {
        await saveApiKey(trimmed)
        setSaved(true)
        setTimeout(onDone, 600)
      } catch (e) {
        setError(`Failed to save: ${(e as Error).message}`)
      }
      return
    }

    if (key.backspace || key.delete) {
      setInput((s) => s.slice(0, -1))
      setError('')
      return
    }

    if (key.escape) {
      process.exit(0)
    }

    if (!key.ctrl && !key.meta && char) {
      setInput((s) => s + char)
      setError('')
    }
  })

  if (saved) {
    return (
      <Box flexDirection="column" gap={1} marginTop={1}>
        <Text color="green">✓ API key saved! Starting DeepSeek Code…</Text>
      </Box>
    )
  }

  const masked = input.length > 0 ? '•'.repeat(input.length) : ''

  return (
    <Box flexDirection="column" gap={1} marginTop={1}>
      <Text bold>Welcome to DeepSeek Code</Text>
      <Text dimColor>To get started, enter your DeepSeek API key.</Text>
      <Text dimColor>Get one at: https://platform.deepseek.com/api_keys</Text>
      <Box marginTop={1} flexDirection="column" gap={1}>
        <Text>DeepSeek API Key:</Text>
        <Box>
          <Text color="cyan">{'> '}</Text>
          <Text>{masked || <Text dimColor>sk-...</Text>}</Text>
          <Text color="cyan">█</Text>
        </Box>
        {error ? (
          <Text color="red">{error}</Text>
        ) : (
          <Text dimColor>Press Enter to confirm · Esc to exit</Text>
        )}
      </Box>
    </Box>
  )
}

