#!/usr/bin/env bun
import React, { useState, useEffect } from 'react'
import { render, Box, Text } from 'ink'
import { App } from './ui/App.js'
import { ApiKeySetup, loadSavedApiKey } from './ui/ApiKeySetup.js'

function Root() {
  const [ready, setReady] = useState(false)
  const [checked, setChecked] = useState(false)

  useEffect(() => {
    // Check env var first, then saved config
    if (process.env.DEEPSEEK_API_KEY) {
      setReady(true)
      setChecked(true)
      return
    }
    loadSavedApiKey().then((key) => {
      if (key) {
        process.env.DEEPSEEK_API_KEY = key
        setReady(true)
      }
      setChecked(true)
    })
  }, [])

  if (!checked) return null

  if (!ready) {
    return (
      <Box flexDirection="column" paddingX={2} paddingY={1}>
        <ApiKeySetup onDone={() => setReady(true)} />
      </Box>
    )
  }

  return (
    <Box flexDirection="column">
      <Text bold color="blue">DeepSeek Code <Text dimColor>v0.1.0</Text></Text>
      <Text dimColor>Type your message and press Enter. /quit or Esc to exit.</Text>
      <Text> </Text>
      <App />
    </Box>
  )
}

const { waitUntilExit } = render(<Root />)
waitUntilExit().then(() => process.exit(0))

